module demorgan(input a, input b, output nand_out, output or_of_nots,
                output nor_out, output and_of_nots);
  assign nand_out    = ~(a & b);
  assign or_of_nots  = ~a | ~b;
  assign nor_out     = ~(a | b);
  assign and_of_nots = ~a & ~b;
endmodule

module demorgan_tb;
  reg a, b;
  wire n1, n2, r1, r2;
  integer i, errors;
  demorgan dut(.a(a), .b(b), .nand_out(n1), .or_of_nots(n2),
               .nor_out(r1), .and_of_nots(r2));
  initial begin
    errors = 0;
    for (i = 0; i < 4; i = i + 1) begin
      {a, b} = i;
      #1;
      $display("a=%b b=%b  NAND=%b A'+B'=%b  NOR=%b A'.B'=%b", a, b, n1, n2, r1, r2);
      if (n1 !== n2 || r1 !== r2) errors = errors + 1;
    end
    if (errors == 0) $display("PASS: De Morgan's laws hold");
    else $display("FAIL: %0d mismatches", errors);
    $finish;
  end
endmodule

module full_adder(input a, input b, input cin, output sum, output cout);
  assign sum  = a ^ b ^ cin;
  assign cout = (a & b) | (cin & (a ^ b));
endmodule

module full_adder_tb;
  reg a, b, cin;
  wire sum, cout;
  reg [1:0] expected;
  integer i, errors;
  full_adder dut(.a(a), .b(b), .cin(cin), .sum(sum), .cout(cout));
  initial begin
    errors = 0;
    for (i = 0; i < 8; i = i + 1) begin
      {a, b, cin} = i;
      #1;
      expected = a + b + cin;
      $display("%b + %b + %b -> cout=%b sum=%b", a, b, cin, cout, sum);
      if ({cout, sum} !== expected) errors = errors + 1;
    end
    if (errors == 0) $display("PASS: all 8 input rows correct");
    else $display("FAIL: %0d rows wrong", errors);
    $finish;
  end
endmodule

module dff(input clk, input d, output reg q);
  always @(posedge clk) q <= d;
endmodule

module dff_tb;
  reg clk, d;
  wire q;
  integer errors;
  dff dut(.clk(clk), .d(d), .q(q));
  always #5 clk = ~clk;
  initial begin
    clk = 0; d = 0; errors = 0;
    @(posedge clk); #1;
    if (q !== 1'b0) errors = errors + 1;
    d = 1; #2;
    $display("d=%b q=%b (no clock edge yet, q must hold)", d, q);
    if (q !== 1'b0) errors = errors + 1;
    @(posedge clk); #1;
    $display("d=%b q=%b (after rising edge, q follows d)", d, q);
    if (q !== 1'b1) errors = errors + 1;
    d = 0; @(posedge clk); #1;
    $display("d=%b q=%b", d, q);
    if (q !== 1'b0) errors = errors + 1;
    if (errors == 0) $display("PASS: q changes only at the clock edge");
    else $display("FAIL: %0d checks failed", errors);
    $finish;
  end
endmodule

module shift4(input clk, input rst, input sin, output reg [3:0] q);
  always @(posedge clk) begin
    if (rst) q <= 4'b0000;
    else     q <= {q[2:0], sin};
  end
endmodule

module shift4_tb;
  reg clk, rst, sin;
  wire [3:0] q;
  reg [3:0] bits;
  integer i, errors;
  shift4 dut(.clk(clk), .rst(rst), .sin(sin), .q(q));
  always #5 clk = ~clk;
  initial begin
    clk = 0; rst = 1; sin = 0; errors = 0; bits = 4'b1011;
    @(posedge clk); #1 rst = 0;
    for (i = 0; i < 4; i = i + 1) begin
      sin = bits[3 - i];
      @(posedge clk); #1;
      $display("shifted in %b -> q = %b", sin, q);
    end
    if (q !== 4'b1011) errors = errors + 1;
    sin = 0; @(posedge clk); #1;
    $display("shifted in 0 -> q = %b", q);
    if (q !== 4'b0110) errors = errors + 1;
    if (errors == 0) $display("PASS: bits 1011 loaded, then shifted left");
    else $display("FAIL: %0d checks failed", errors);
    $finish;
  end
endmodule

module decade_counter(input clk, input rst, output reg [3:0] count);
  always @(posedge clk) begin
    if (rst)               count <= 4'd0;
    else if (count == 4'd9) count <= 4'd0;
    else                   count <= count + 4'd1;
  end
endmodule

module decade_counter_tb;
  reg clk, rst;
  wire [3:0] count;
  integer i, errors;
  decade_counter dut(.clk(clk), .rst(rst), .count(count));
  always #5 clk = ~clk;
  initial begin
    clk = 0; rst = 1; errors = 0;
    @(posedge clk); #1 rst = 0;
    if (count !== 4'd0) errors = errors + 1;
    for (i = 1; i <= 12; i = i + 1) begin
      @(posedge clk); #1;
      $display("edge %0d: count = %0d", i, count);
      if (count !== i % 10) errors = errors + 1;
    end
    if (errors == 0) $display("PASS: counts 0 to 9 and wraps");
    else $display("FAIL: %0d wrong values", errors);
    $finish;
  end
endmodule

module turnstile(input clk, input rst, input coin, input push,
                 output unlocked);
  reg state;            // 0 = LOCKED, 1 = UNLOCKED
  assign unlocked = state;
  always @(posedge clk) begin
    if (rst) state <= 1'b0;
    else if (state == 1'b0 && coin) state <= 1'b1;
    else if (state == 1'b1 && push) state <= 1'b0;
  end
endmodule

module turnstile_tb;
  reg clk, rst, coin, push;
  wire unlocked;
  integer errors;
  turnstile dut(.clk(clk), .rst(rst), .coin(coin), .push(push), .unlocked(unlocked));
  always #5 clk = ~clk;
  initial begin
    clk = 0; rst = 1; coin = 0; push = 0; errors = 0;
    @(posedge clk); #1 rst = 0;
    if (unlocked !== 1'b0) errors = errors + 1;
    push = 1; @(posedge clk); #1 push = 0;
    $display("push while locked   -> unlocked=%b", unlocked);
    if (unlocked !== 1'b0) errors = errors + 1;
    coin = 1; @(posedge clk); #1 coin = 0;
    $display("coin                -> unlocked=%b", unlocked);
    if (unlocked !== 1'b1) errors = errors + 1;
    coin = 1; @(posedge clk); #1 coin = 0;
    $display("extra coin          -> unlocked=%b", unlocked);
    if (unlocked !== 1'b1) errors = errors + 1;
    push = 1; @(posedge clk); #1 push = 0;
    $display("push while unlocked -> unlocked=%b", unlocked);
    if (unlocked !== 1'b0) errors = errors + 1;
    if (errors == 0) $display("PASS: turnstile follows its state diagram");
    else $display("FAIL: %0d checks failed", errors);
    $finish;
  end
endmodule
